import numpy as np

def transform(grid):
    a=np.array(grid,dtype=int)
    h,w=a.shape
    rows=[r for r in range(h) if np.all(a[r,:]==2)]
    cols=[c for c in range(w) if np.all(a[:,c]==2)]
    if rows:
        axis,line=0,rows[0]
    elif cols:
        axis,line=1,cols[0]
    else:
        return a.tolist()
    bg=int(np.bincount(a.ravel()).argmax())
    coords=np.argwhere((a!=bg)&(a!=2))
    if len(coords)==0: return a.tolist()
    lo,hi=int(coords[:,axis].min()),int(coords[:,axis].max())
    if hi<line:
        delta=line-1-hi; mark=lo+delta-1
    elif lo>line:
        delta=line+1-lo; mark=hi+delta+1
    else:
        delta=0; mark=None
    out=np.full_like(a,bg)
    if axis==0: out[line,:]=2
    else: out[:,line]=2
    for r,c in coords:
        nr,nc=(int(r+delta),int(c)) if axis==0 else (int(r),int(c+delta))
        if 0<=nr<h and 0<=nc<w: out[nr,nc]=int(a[r,c])
    if mark is not None and 0<=mark<(h if axis==0 else w):
        if axis==0: out[mark,:]=8
        else: out[:,mark]=8
    return out.tolist()
